insert into public.site_content(key,title,body) values
('about','من نحن','سوق الشورجة منصة إعلانات عراقية تساعد الأفراد وأصحاب الأعمال على عرض المنتجات والخدمات والتواصل مع المهتمين. نحن وسيط لعرض الإعلانات ولا نضمن جودة المنتجات أو إتمام المعاملات. تحقق من البائع والمنتج واتفق بوضوح على شروط البيع قبل الدفع.'),
('contact','اتصل بنا','للاستفسارات استخدم قناة Telegram المعروضة أسفل الموقع. لا ترسل كلمات مرور أو رموز تحقق أو صور وثائق حساسة عبر المحادثات. للإبلاغ عن إعلان استخدم زر البلاغ داخل صفحة الإعلان. أوقات الاستجابة تختلف حسب حجم الطلبات.'),
('privacy','سياسة الخصوصية','نعالج بيانات الحساب والملف والإعلانات والمراسلات لتشغيل المنصة ومنع إساءة الاستخدام. بيانات التسجيل تُدار عبر Supabase Auth، والملفات عبر Storage. رقم الهاتف لا يظهر في الملف العام إلا باختيارك. لا تُعرض كلمات المرور أو البريد الخاص للعامة. المراسلات متاحة لأطرافها فقط وليست مشفرة من طرف إلى طرف. قد تراجع الإدارة البلاغات والبيانات التشغيلية المسموح بها. يمكنك طلب حذف حسابك من الإعدادات. روابط الوسائط الموقعة مؤقتة ويمكن أن تبقى صالحة حتى انتهاء مدتها. يجب تحديث هذه السياسة بعد تحديد بيانات الجهة المشغلة ومدد الاحتفاظ الفعلية.'),
('terms','الشروط والأحكام','باستخدام المنصة تلتزم بتقديم معلومات صحيحة واحترام الآخرين والقوانين النافذة. يتحمل المعلن مسؤولية وصف المنتج وملكيته وصحة السعر والتواصل. يجوز مراجعة أو إخفاء المحتوى المخالف وتعطيل الحسابات المسيئة. لا تضمن المنصة إتمام الصفقات أو تعوض الخسائر تلقائياً. هذه نصوص تشغيلية عامة وليست استشارة قانونية، وتحتاج مراجعة مناسبة لطبيعة الجهة المشغلة.'),
('usage','سياسة الاستخدام','يُمنع انتحال الهوية والاحتيال والإزعاج وجمع بيانات المستخدمين دون إذن ومحاولة تجاوز الصلاحيات أو الترويج. استخدم الرسائل للتواصل بشأن الإعلانات. لا تشارك رموز التأكيد ولا تحول دفعات مقدمة لبائع مجهول دون تحقق.'),
('advertising','سياسة الإعلانات','اكتب عنواناً واضحاً وسعراً صحيحاً وموقعاً مناسباً وصوراً تخص المنتج. لا تنشر إعلانات مكررة أو مضللة ولا مواد ممنوعة. الترويج المجاني يمنح لأول إعلان منشور مرة واحدة للحساب ولا يعود عند حذف الإعلان. المحتوى الإعلاني الرئيسي قابل للإدارة، ولا يعني ظهوره أن المنصة تضمن المعلن.'),
('content_policy','سياسة المحتوى','يُمنع المحتوى غير القانوني والاستغلال والعنف والتهديد وخطاب الكراهية ونشر البيانات الخاصة أو انتهاك حقوق الملكية. تُراجع البلاغات بحسب السياق وقد يُخفى المحتوى أو يُحذف. قدّم معلومات كافية في البلاغ ولا تستخدمه لمضايقة الآخرين.'),
('faq','الأسئلة الشائعة','كيف أنشئ حساباً؟ سجّل بالبريد ثم أكد رسالة التسجيل. كيف أنشر إعلاناً؟ اختر نشر إعلان وأدخل التفاصيل وارفع الصور. هل الترويج مجاني؟ لأول إعلان منشور فقط، مرة واحدة للحساب. كيف أحذف إعلاناً؟ من إعلاناتي بعد تأكيد الحذف. لماذا لا تظهر صور بعد مدة طويلة؟ أعد تحميل الصفحة لتجديد الروابط المؤقتة. كيف أبلغ؟ من تفاصيل الإعلان.'),
('blog','المدونة','دليل شراء آمن: قارن الأسعار، افحص المنتج في مكان آمن، لا تشارك رموز التحقق، واحتفظ بتفاصيل الاتفاق. دليل إعلان ناجح: استخدم صوراً واضحة واذكر العيوب والسعر والموقع وشروط التسليم. المحتوى هنا قابل للتحرير من المدير، وليس نظام تدوين متعدد المقالات بعد.'),
('jobs','الوظائف','يمكن نشر فرص العمل ضمن فئة الوظائف مع توضيح المهام والموقع وطريقة التواصل. لا توجد وظائف معلنة لدى فريق المنصة حالياً. لا تدفع رسوماً للحصول على مقابلة ولا ترسل بيانات مالية أو وثائق شخصية قبل التحقق من الجهة.'),
('help','المساعدة','تأكد من اتصالك ومن تأكيد البريد. إذا فشل الرفع تحقق من النوع والحجم؛ الحد الحالي 4MB للملف. عند تعذر الدخول استخدم استعادة كلمة المرور. تغيير الهاتف يحتاج رمز SMS. لا تستخدم الموقع مباشرة من ملف HTML؛ يجب تشغيل الخادم.'),
('support','مركز الدعم','للإبلاغ عن مشكلة صف الخطوات والوقت ونوع الجهاز، دون إرسال كلمات مرور أو رموز تحقق. استخدم رابط التواصل الرسمي في أسفل الصفحة. للحالات المتعلقة بمحتوى مخالف استخدم نظام البلاغات. لا يوجد نظام تذاكر دعم متكامل في هذه النسخة.')
insert into public.site_content(key,title,body,kind,settings) values('socials','التواصل الرسمي','روابط التواصل','settings','{"telegram":"https://t.me/HarryScloser6","youtube":""}') on conflict do nothing;
